package com.ramka.domain.utilimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.update/** * Защита от спама для текстового сигнала «вам пытаются отправить файл» (только в памяти). * * Сигнал уходит, если одновременно выполнено два условия: *  1. по этому файловому сообщению сигнал ещё не отправлялся (повторы «Повторить» не шлют новый); *  2. по этому контакту сигнал не отправлялся последние [cooldownMillis] (по умолчанию 5 минут). * * После перезапуска процесса память пуста — в худшем случае уйдёт один лишний сигнал. * [notifiedFiles] нужен UI: подпись «Собеседнику отправлено уведомление» под статусом файла. */class OfflineSignalTracker(    private val now: () -> Long = { System.currentTimeMillis() },    private val cooldownMillis: Long = DEFAULT_COOLDOWN_MILLIS) {    private val lock = Any()    private val lastSignalAt = HashMap<String, Long>()    private val notified = MutableStateFlow<Set<String>>(emptySet())    /** localId файловых сообщений, по которым сигнал реально поставлен на отправку. */    val notifiedFiles: StateFlow<Set<String>> = notified.asStateFlow()    /**     * Резервирует право на сигнал. true — можно слать (окно контакта уже занято до     * [markNotified]/[rollback]), false — слать нельзя.     */    fun tryAcquire(contactId: String, fileMessageId: String): Boolean = synchronized(lock) {        if (fileMessageId in notified.value) return false        val last = lastSignalAt[contactId]        if (last != null) {            val elapsed = now() - last            // elapsed < 0 — часы переведены назад: считаем окно ещё открытым, а не «прошло навсегда».            if (elapsed < cooldownMillis) return false        }        lastSignalAt[contactId] = now()        true    }    fun markNotified(fileMessageId: String) {        notified.update { it + fileMessageId }    }    /** Сигнал не удалось поставить на отправку — освобождаем окно контакта. */    fun rollback(contactId: String) {        synchronized(lock) { lastSignalAt.remove(contactId) }    }    companion object {        const val DEFAULT_COOLDOWN_MILLIS: Long = 5 * 60 * 1000L    }}